//Problem Statement: Write a Java program to print all even numbers from 1 to 50 using a for loop.
package task;

public class EvenLoop {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
		for(int i=1;i<=50;i++){
			if(i%2==0){
			System.out.println(i);
			}
		}
	}

}
